const input = $input.first().json || {};
// El sub-workflow puede recibir el sql en distintos shapes según cómo lo invoque el agente
const sql = input.sql
         || input.query
         || input.body?.sql
         || input.body?.query
         || (input.json && (input.json.sql || input.json.query))
         || '';
if (!sql || !String(sql).trim()) {
  throw new Error('Parámetro sql requerido. Inputs recibidos: ' + JSON.stringify(input));
}
const sqlStr = String(sql).trim();
const normalized = sqlStr.toUpperCase();
if (!normalized.startsWith('SELECT') && !normalized.startsWith('WITH')) {
  throw new Error('Solo se permiten queries SELECT o WITH. Se recibió: ' + normalized.split(/\s+/)[0]);
}
return [{ json: { sql: sqlStr } }];

const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { result: 'Sin resultados', rows: [], count: 0 } }];
return [{ json: { result: 'OK', rows, count: rows.length } }];
